--1. 分类映射关系表增加证券品种、证券品种名称字段
alter table FIN_PRODUCT_CLASS add sec_type VARCHAR2(50);
comment on column FIN_PRODUCT_CLASS.sec_type
  is '证券品种';

alter table FIN_PRODUCT_CLASS add sec_type_name VARCHAR2(200);
comment on column FIN_PRODUCT_CLASS.sec_type_name
  is '证券品种名称';


--2.数据字典-证券品种增加枚举值：其他债权类资产
DELETE FROM SYS_DATADICT_LIST WHERE DICT_CODE = 'SEC_TYPE' AND ITEM_CODE = '13';

--3.数据字典-计划类资产类型增加枚举值：未上市公司股权（17）
